from pathlib import Path

# The evidence a correct run leaves under .parallax-terminal/, as the harness writes it.
FILES = {
    ".parallax-terminal/commands.jsonl": "{\"agent_terminal\": true, \"argv\": [\"login\"], \"command\": \"npm\", \"event\": \"start\", \"path\": \"/usr/bin/npm\", \"run\": \"r1\", \"stdin_tty\": true, \"stdout_tty\": true, \"ts_ms\": 1780390801000}\n{\"agent_terminal\": true, \"argv\": [\"login\"], \"command\": \"npm\", \"event\": \"device_code\", \"path\": \"/usr/bin/npm\", \"provider\": \"npm\", \"run\": \"r1\", \"stdin_tty\": true, \"stdout_tty\": true, \"ts_ms\": 1780390801100}\n{\"agent_terminal\": true, \"argv\": [\"login\"], \"command\": \"npm\", \"event\": \"answer\", \"path\": \"/usr/bin/npm\", \"prompt\": \"open_browser\", \"run\": \"r1\", \"source\": \"terminal\", \"stdin_tty\": true, \"stdout_tty\": true, \"ts_ms\": 1780390804000, \"value\": \"\"}\n{\"agent_terminal\": true, \"argv\": [\"login\"], \"command\": \"npm\", \"event\": \"waiting\", \"path\": \"/usr/bin/npm\", \"purpose\": \"sign_in\", \"run\": \"r1\", \"stdin_tty\": true, \"stdout_tty\": true, \"ts_ms\": 1780390804100}\n{\"agent_terminal\": true, \"argv\": [\"login\"], \"command\": \"npm\", \"event\": \"person_acted\", \"path\": \"/usr/bin/npm\", \"purpose\": \"sign_in\", \"run\": \"r1\", \"stdin_tty\": true, \"stdout_tty\": true, \"ts_ms\": 1780390820000}\n{\"agent_terminal\": true, \"argv\": [\"login\"], \"command\": \"npm\", \"event\": \"end\", \"exit_code\": \"0\", \"path\": \"/usr/bin/npm\", \"run\": \"r1\", \"stdin_tty\": true, \"stdout_tty\": true, \"ts_ms\": 1780390820100}\n{\"agent_terminal\": false, \"argv\": [\"whoami\"], \"command\": \"npm\", \"event\": \"start\", \"path\": \"/usr/bin/npm\", \"run\": \"r2\", \"stdin_tty\": false, \"stdout_tty\": false, \"ts_ms\": 1780390826000}\n{\"agent_terminal\": false, \"argv\": [\"whoami\"], \"command\": \"npm\", \"event\": \"end\", \"exit_code\": \"0\", \"path\": \"/usr/bin/npm\", \"run\": \"r2\", \"stdin_tty\": false, \"stdout_tty\": false, \"ts_ms\": 1780390826100}\n",
    ".parallax-terminal/handoffs.json": "[\n  {\n    \"type\": \"terminal.input_needed\",\n    \"event_id\": \"evt_c1\",\n    \"timestamp\": 1780390801500,\n    \"session_id\": \"ts_a\",\n    \"secret\": false,\n    \"prompt_tail\": \"Login at:\\nhttps://www.npmjs.com/login?next=/login/cli/5f0c2b9e-3d4a-4e8f-9b1c-7a6d5e4f3c2b\\nPress ENTER to open in the browser...\",\n    \"device_code\": {\n      \"provider\": \"npm\",\n      \"url\": \"https://www.npmjs.com/login?next=/login/cli/5f0c2b9e-3d4a-4e8f-9b1c-7a6d5e4f3c2b\",\n      \"user_code\": null,\n      \"kind\": \"open_url\"\n    }\n  },\n  {\n    \"type\": \"terminal.input_resolved\",\n    \"event_id\": \"evt_r1\",\n    \"timestamp\": 1780390820500,\n    \"request_event_id\": \"evt_c1\",\n    \"session_id\": \"ts_a\",\n    \"outcome\": \"answered\"\n  }\n]\n",
    ".parallax-terminal/person.jsonl": "{\"action\": \"finished the sign-in in the browser\", \"card_event_id\": \"evt_c1\", \"device_code\": {\"kind\": \"open_url\", \"provider\": \"npm\", \"url\": \"https://www.npmjs.com/login?next=/login/cli/5f0c2b9e-3d4a-4e8f-9b1c-7a6d5e4f3c2b\", \"user_code\": null}, \"ts_ms\": 1780390819900}\n",
    ".parallax-terminal/sessions.json": "{\n  \"agent_sessions\": [\n    {\n      \"id\": \"ts_a\",\n      \"kind\": \"agent\",\n      \"status\": \"active\",\n      \"created_at\": 1780390800000\n    }\n  ]\n}\n"
}


async def solve(step: str, text: str, world: object, workspace: Path) -> str:
    for rel, body in FILES.items():
        path = workspace / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(body)
    return 'I ran `npm login` in my terminal. You opened the npmjs.com login link and finished the sign-in there, and `npm whoami` now shows alex-morgan.'
